<script>
 import {prototypePower} from '$lib/simulation.js';
 let {reportedAt}=$props();let now=$derived(Date.parse(reportedAt||new Date().toISOString()));
 let samples=$derived(Array.from({length:21},(_,i)=>prototypePower(now-(20-i)*3000)));
 let maximum=$derived(Math.max(1000,...samples.flatMap(p=>[p.solar,p.consumption])));
 const line=key=>samples.map((p,i)=>`${i*30},${110-p[key]/maximum*95}`).join(' ');
</script>
<section class="power-trend"><div class="trend-title"><div><span>POWER ACTIVITY</span><h2>Your energy in motion</h2></div><span class="trend-window">Last 60 seconds · kW</span></div><svg viewBox="0 0 600 125" role="img" aria-label="Solar production and household demand over the last sixty seconds" preserveAspectRatio="none"><path d="M0 110H600M0 62H600M0 15H600" class="trend-grid"/><polyline points={line('solar')} class="trend-solar"/><polyline points={line('consumption')} class="trend-usage"/></svg><div class="trend-legend"><span><i></i>Solar production</span><span><i class="usage"></i>Household demand</span><span class="trend-now">Now</span></div></section>
<style>.power-trend{background:#fbfdf8;border:1px solid #dce6d4;border-radius:18px;padding:22px;margin:20px 0}.trend-title{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.trend-title h2{font-size:18px!important;margin:6px 0 14px}.trend-title>div>span{font-size:10px;letter-spacing:.1em;color:#6d8058}.trend-window,.trend-legend{font-size:11px;color:#687b55}.power-trend svg{width:100%;height:145px;overflow:visible}.trend-grid{stroke:#e3eadc;stroke-dasharray:3 4;fill:none}.power-trend polyline{fill:none;stroke-width:2.5;stroke-linejoin:round;stroke-linecap:round;vector-effect:non-scaling-stroke}.trend-solar{stroke:#9bc956}.trend-usage{stroke:#496d51}.trend-legend{display:flex;gap:18px;align-items:center;margin-top:12px;flex-wrap:wrap}.trend-legend i{display:inline-block;width:8px;height:8px;background:#9bc956;border-radius:2px;margin-right:6px}.trend-legend .usage{background:#496d51}.trend-now{margin-left:auto}@media(max-width:640px){.power-trend{padding:18px}.power-trend svg{height:110px}}</style>
